const addImageDropdown=(select,srcForValue)=>{if(select.dataset.imageDropdown)return;select.dataset.imageDropdown='1';if(select.matches('select[data-event="npc"]'))select.dataset.visualNpcPicker='1';const picker=document.createElement('div'),toggle=document.createElement('button'),menu=document.createElement('div'),refresh=()=>{const option=select.selectedOptions[0];toggle.replaceChildren();if(!select.value){toggle.textContent=option?.textContent||'選択してください';return}const image=document.createElement('img'),label=document.createElement('span');image.src=srcForValue(select.value);image.alt='';label.textContent=option?.textContent||select.value;toggle.append(image,label)};picker.className='npc-visual-picker image-dropdown';toggle.type='button';toggle.className='npc-visual-picker-toggle';menu.className='npc-visual-picker-menu';menu.hidden=true;[...select.options].filter(option=>option.value).forEach(option=>{const button=document.createElement('button'),image=document.createElement('img'),label=document.createElement('span');button.type='button';image.src=srcForValue(option.value);image.alt='';label.textContent=option.textContent;button.append(image,label);button.onclick=()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));menu.hidden=true;refresh()};menu.append(button)});toggle.onclick=()=>menu.hidden=!menu.hidden;picker.append(toggle,menu);select.style.display='none';select.after(picker);select.addEventListener('change',refresh);refresh()};
