window.runCardBattleSequence=({content,player,enemy,showActions=false,onOther,onPick,onFinish}={})=>{
  if(!content||!player||!enemy)return;
  const hands=['gu','choki','pa'],handName={gu:'グー',choki:'チョキ',pa:'パー'},handAsset={gu:'game-assets/battle/janken-gu.webp',choki:'game-assets/battle/janken-choki.webp',pa:'game-assets/battle/janken-pa.webp'},escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char])),cardHtml=(card,extra='',side='')=>'<article class="battle-card '+extra+'" style="--card-bg:'+card.color+'">'+(side?'<span class="battle-side-label">'+side+'</span>':'')+'<b class="battle-card-name">'+escape(card.name)+'</b><img src="npc-light/'+card.id+'.png" alt="'+escape(card.name)+'"><div class="battle-hands">'+card.hands.map((hand,index)=>'<span data-round="'+index+'" aria-label="'+handName[hand]+'"><img src="'+handAsset[hand]+'" alt="'+handName[hand]+'"></span>').join('')+'</div></article>',beats=(left,right)=>left===right?0:(left==='gu'&&right==='choki')||(left==='choki'&&right==='pa')||(left==='pa'&&right==='gu')?1:-1,rounds=player.hands.map((hand,index)=>beats(hand,enemy.hands[index])),wins=rounds.filter(value=>value===1).length,losses=rounds.filter(value=>value===-1).length,draw=wins===losses,wait=ms=>new Promise(resolve=>setTimeout(resolve,ms)),startConfetti=match=>{const colors=['#f04f85','#f5c842','#4ab5e8','#7acb6c','#9b68df','#ff8b43'];match.insertAdjacentHTML('afterbegin','<div class="battle-kusudama" aria-hidden="true">'+Array.from({length:42},(_,index)=>'<i style="--x:'+(Math.random()*100).toFixed(1)+'%;--d:'+(1.6+Math.random()*1.8).toFixed(2)+'s;--delay:'+(-Math.random()*1.8).toFixed(2)+'s;--c:'+colors[index%colors.length]+'"></i>').join('')+'</div>')};
  const showStart=()=>{content.innerHTML='<div class="battle-start-screen" aria-live="assertive">バトル<br>スタート！</div>';setTimeout(runBattle,800)};
  const runBattle=async()=>{
    const actionMarkup=showActions?'<div class="battle-actions" hidden><button type="button" class="layout-place battle-other">他のカードと戦う</button><button type="button" class="layout-place battle-again">別のカードを選ぶ</button></div>':'';
    content.innerHTML='<section class="battle-match battle-sequence"><div class="battle-lane enemy">'+cardHtml(enemy,'enemy-card','相手')+'</div><div class="battle-vs battle-vs-intro" hidden aria-hidden="true">VS</div><div class="battle-rounds battle-rounds-sequence"></div><p class="battle-result" hidden></p><section class="coin-toss" hidden></section><div class="battle-lane player">'+cardHtml(player,'player-card','自分')+'</div><p class="battle-score" hidden>'+wins+'勝 '+losses+'敗 '+(3-wins-losses)+'分</p>'+actionMarkup+'</section>';
    const match=content.querySelector('.battle-match'),vs=match.querySelector('.battle-vs-intro'),roundsBox=match.querySelector('.battle-rounds'),result=match.querySelector('.battle-result'),panel=match.querySelector('.coin-toss'),score=match.querySelector('.battle-score'),actions=match.querySelector('.battle-actions'),addRound=index=>{roundsBox.insertAdjacentHTML('beforeend','<div class="battle-round-group battle-round-pending"><span class="battle-round-number">'+(index+1)+'回戦</span><div class="battle-round"><strong></strong></div></div>');return roundsBox.lastElementChild},revealRound=(group,value,extra='')=>{const bubble=group.querySelector('.battle-round');group.classList.remove('battle-round-pending');bubble.classList.add(value===1?'win':value===-1?'lose':'draw');bubble.innerHTML=extra?'<small>'+extra+'</small><strong>'+(value===1?'勝ち':'負け')+'</strong>':'<strong>'+(value===1?'勝ち':value===-1?'負け':'あいこ')+'</strong>'},finish=won=>{result.hidden=false;result.className='battle-result '+(won?'win':'lose');result.textContent=won?'あなたの勝ち！':'あなたの負け…';score.hidden=false;if(won)startConfetti(match);if(showActions){actions.hidden=false;actions.querySelector('.battle-other').onclick=onOther;actions.querySelector('.battle-again').onclick=onPick}onFinish?.(won)};
    await wait(1000);vs.hidden=false;await wait(2000);vs.hidden=true;
    for(let index=0;index<rounds.length;index++){const group=addRound(index);await wait(500);revealRound(group,rounds[index])}
    await wait(500);if(!draw){finish(wins>losses);return}
    panel.hidden=false;panel.innerHTML='<i class="coin-choice-preview" aria-hidden="true"></i><p>表か裏を選んで最終勝負！</p><div><button type="button" data-face="表">表を選ぶ</button><button type="button" data-face="裏">裏を選ぶ</button></div>';
    panel.querySelectorAll('button').forEach(button=>button.onclick=async()=>{panel.querySelectorAll('button').forEach(item=>item.disabled=true);const selected=button.dataset.face,landed=Math.random()<.5?'表':'裏',won=selected===landed,faceClass=selected==='表'?'heads':'tails';panel.innerHTML='<i class="coin-choice-preview coin-spinning" aria-label="コインを回しています"></i>';const spinner=panel.querySelector('.coin-spinning');let spinFrame=0;const spin=()=>{spinner.style.backgroundPositionX=-(spinFrame++%8)*spinner.clientWidth+'px'};spin();const timer=setInterval(spin,100);await wait(2000);clearInterval(timer);panel.innerHTML='<i class="coin-choice-preview is-'+faceClass+'" aria-label="'+selected+'のコイン"></i>';const group=addRound(3);group.classList.add('coin-round');revealRound(group,won?1:-1,'コイントス：'+landed);finish(won)});
  };
  showStart();
};

